        {
            "class": "JointInput",
            "doc": "\nDefines the relationship between the two joint geometries as a rigid joint.\nReturns true if successful.\n",
            "name": "setAsRigidJointMotion",
            "namespace": "adsk.fusion",
            "signature": "() -> bool",
            "type": "function"
        },
        {
            "class": "JointInput",
            "doc": "Specifies the angle between two input geometries. This is effectively the\nangle between the two primary axes of the input geometries. When a new\nJointInput object is created, this value defaults to zero. When the joint\nis created this will become the value of the parameter that controls the joint angle.\nWhen using a real value to define the angle, the value is in radians. When\nusing a string the expression is evaluated using the document default units for angles.",
            "name": "angle",
            "namespace": "adsk.fusion",
            "type": "property"
        },
        {
            "class": "JointInput",
            "doc": "Specifies the offset between two input geometries. This is effectively the\noffset distance between the two planes defined by the primary and secondary axes\nof the input geometries. When a new JointInput object is created, this value defaults to zero.\nWhen the joint is created this will become the value of the parameter that controls the joint offset.\nWhen using a real value to define the offset, the value is in centimeters. When\nusing a string the expression is evaluated using the document default units for distance.",
            "name": "offset",
            "namespace": "adsk.fusion",
            "type": "property"
        }
    ],
    "message": "API documentation query completed",
    "success": true
